-- 006: catálogo ampliado (CEJ, REDAM y rubros estilo Arequipa) + noticias
-- oficiales con fotos. Idempotente: puede repetirse sin duplicar.
UPDATE servicios SET url='https://cej.pj.gob.pe/', description='Consulta el estado de tus expedientes judiciales por número, partes o materia en el portal nacional CEJ.', status='activo' WHERE slug='consulta-expedientes';
INSERT INTO servicios (slug, name, summary, description, category_id, url, link_type, icon, sort_order, featured, status) VALUES
('redam-deudores-alimentarios','Registro de Deudores Alimentarios','Consulta el registro de deudores alimentarios morosos y genera certificados.','Verifica si una persona está registrada como deudora alimentaria morosa y genera certificados oficiales. Si el sistema está en mantenimiento, acude a REDIJU o un MAC.',(SELECT id FROM categorias WHERE slug='digital'),'https://redam.pj.gob.pe/','externo','idcard',15,0,'activo'),
('odanc-control','ODANC · Control y Quejas','Presenta quejas por inconducta de magistrados y servidores judiciales.','La Oficina Descentralizada de la Autoridad Nacional de Control recibe quejas y supervisa la conducta de magistrados y servidores del distrito judicial. Canal pendiente de validación.',(SELECT id FROM categorias WHERE slug='atencion'),NULL,'externo','shield',16,0,'inactivo'),
('violencia-familiar','Módulo de Violencia Familiar','Atención de denuncias y medidas de protección frente a la violencia familiar.','Los módulos y juzgados competentes reciben denuncias por violencia contra la mujer e integrantes del grupo familiar y dictan medidas de protección. Información orientativa; canal pendiente de validación.',(SELECT id FROM categorias WHERE slug='atencion'),NULL,'externo','heart',17,0,'inactivo'),
('formularios','Formularios y Formatos','Formatos descargables para tus trámites judiciales.','Formatos para mesa de partes, apersonamientos y otros escritos judiciales. Enlace pendiente de validación.',(SELECT id FROM categorias WHERE slug='digital'),NULL,'externo','clip',18,0,'inactivo'),
('competencia-territorial','Competencia Territorial','Conoce qué sede y juzgado corresponde según la materia y el lugar.','Orientación sobre qué órgano jurisdiccional y sede es competente según materia y territorio. Información pendiente de validación.',(SELECT id FROM categorias WHERE slug='institucional'),NULL,'externo','map',19,0,'inactivo')
ON DUPLICATE KEY UPDATE name=VALUES(name), summary=VALUES(summary), description=VALUES(description), category_id=VALUES(category_id), url=VALUES(url), icon=VALUES(icon), sort_order=VALUES(sort_order), status=VALUES(status);
INSERT INTO servicio_palabras_clave (service_id, keyword)
SELECT s.id, k.keyword FROM servicios s JOIN (
SELECT 'consulta-expedientes' AS slug, 'cej' AS keyword UNION ALL
SELECT 'redam-deudores-alimentarios', 'deudores' UNION ALL
SELECT 'redam-deudores-alimentarios', 'alimentos' UNION ALL
SELECT 'odanc-control', 'queja' UNION ALL
SELECT 'odanc-control', 'control' UNION ALL
SELECT 'violencia-familiar', 'denuncia' UNION ALL
SELECT 'violencia-familiar', 'protección' UNION ALL
SELECT 'formularios', 'formatos'
) AS k ON k.slug = s.slug
ON DUPLICATE KEY UPDATE keyword=VALUES(keyword);
INSERT INTO noticias (id, title, summary, body, category, image, photos, external, featured, official, status, published_at) VALUES
('oficial-dia-juez-2026','Corte de San Martín conmemoró el Día del Juez y la Jueza con ceremonia solemne','Ceremonia en Moyobamba con homenaje a magistrados y reconocimiento a los órganos jurisdiccionales que superaron sus metas de producción.','La Corte Superior de Justicia de San Martín conmemoró el Día del Juez y la Jueza con una ceremonia solemne en Moyobamba, con liturgia de acción de gracias, reseña histórica y reconocimiento a los órganos jurisdiccionales destacados.','Institucional','assets/noticia-diajuez-1.jpg','[{"src":"assets/noticia-diajuez-1.jpg"},{"src":"assets/noticia-diajuez-2.jpg"}]','https://www.pj.gob.pe/wps/wcm/connect/cortesuperiorsanmartinpj/s_csj_san_martin_nuevo/as_inicio/as_imagen_prensa/as_noticias/csjsm_n_dia_juez_2026',1,1,'activo','2026-08-04'),
('oficial-condena-35-2026','Juzgado de Tarapoto condena a 35 años de prisión a dos coautores de asesinato','El Juzgado Penal Colegiado de Tarapoto condenó a dos coautores del asesinato del empresario Jaime Ramírez Navarro, con reparación civil de S/ 101 000.','El Juzgado Penal Colegiado Supraprovincial Permanente de Tarapoto condenó a 35 años de pena privativa de libertad a dos coautores de los delitos de homicidio calificado y robo agravado, con reparación civil de S/ 101 000, inhabilitación para portar armas y captura inmediata para la ejecución de la pena.','Institucional','assets/noticia-condena-1.jpg','[{"src":"assets/noticia-condena-1.jpg"}]','https://www.pj.gob.pe/wps/wcm/connect/cortesuperiorsanmartinpj/s_csj_san_martin_nuevo/as_inicio/as_imagen_prensa/as_noticias/csjsm_n_prision_2026',1,1,'activo','2026-07-30'),
('oficial-foto-2026','Corte de San Martín obtiene tercer lugar en concurso nacional de fotografía','La fotografía premiada, titulada "Escuchar para proteger", retrata una jornada de justicia itinerante en la comunidad nativa de Canoapuerto.','La Corte obtuvo el tercer lugar en el concurso nacional de fotografía "Justicia que Trasciende", en el I Congreso Nacional de Justicia Itinerante. La fotografía "Escuchar para proteger", de la Oficina de Imagen Institucional, retrata una jornada itinerante en la comunidad nativa de Canoapuerto con el pueblo indígena Shawi.','Actividades',NULL,'[]','https://www.pj.gob.pe/wps/wcm/connect/cortesuperiorsanmartinpj/s_csj_san_martin_nuevo/as_inicio/as_imagen_prensa/as_noticias/csjsm_n_tercer_lugar',1,1,'activo','2026-07-17'),
('oficial-laboratorio-2026','Presidente de la Corte gestiona terreno para moderno laboratorio de criminalística en Tarapoto','Terreno de 5 000 m2 en Cacatachi para peritajes biológicos, químicos y balísticos sin derivar muestras a otras ciudades.','El presidente de la Corte gestionó ante la Municipalidad Provincial de San Martín la donación de un terreno de aproximadamente 5 000 metros cuadrados en el distrito de Cacatachi para construir un moderno laboratorio de criminalística con ambientes de peritajes biológicos, químicos, balísticos y de alta complejidad.','Institucional','assets/noticia-laboratorio-1.jpg','[{"src":"assets/noticia-laboratorio-1.jpg"},{"src":"assets/noticia-laboratorio-2.jpg"}]','https://www.gob.pe/institucion/csjsanmartin/noticias/1390315-presidente-de-la-corte-de-san-martin-gestiona-terreno-para-implementar-moderno-laboratorio-de-criminalistica-en-tarapoto',0,1,'activo','2026-05-12'),
('oficial-magistrados-2026','Corte fortalece la justicia con promoción y designación de magistrados','Magistrados provisionales y supernumerarios en Moyobamba, Juanjuí y Yurimaguas garantizan la continuidad del servicio.','La Presidencia dispuso la promoción y designación de magistrados provisionales y supernumerarios en órganos jurisdiccionales de Moyobamba, Juanjuí y Yurimaguas, tras la designación de magistrados como presidentes de Jurados Electorales Especiales, asegurando la continuidad del servicio de justicia.','Institucional','assets/noticia-magistrados-1.jpg','[{"src":"assets/noticia-magistrados-1.jpg"},{"src":"assets/noticia-magistrados-2.jpg"}]','https://www.gob.pe/institucion/csjsanmartin/noticias/1405658-corte-de-san-martin-fortalece-la-administracion-de-justicia-con-nuevas-promociones-y-designaciones-de-magistrados',0,1,'activo','2026-05-20'),
('oficial-feria-digital-2026','Corte presenta buenas prácticas digitales en feria nacional de Huánuco','Transcriptor de audiencias con IA, automatización de remates y DepoFile ante diez cortes del país.','En la III Feria de Transformación Digital Judicial de Huánuco, la Corte presentó el transcriptor de audiencias con inteligencia artificial, la automatización de remates judiciales electrónicos y el software DepoFile para depósitos judiciales, ante la Presidenta del Poder Judicial y diez cortes del país.','Actividades','assets/noticia-feriadigital-1.jpg','[{"src":"assets/noticia-feriadigital-1.jpg"},{"src":"assets/noticia-feriadigital-2.jpg"}]','https://www.gob.pe/institucion/csjsanmartin/noticias/1389551-corte-de-san-martin-presenta-innovadoras-buenas-practicas-en-feria-nacional-de-transformacion-digital-judicial-en-huanuco',0,1,'activo','2026-04-24')
ON DUPLICATE KEY UPDATE title=VALUES(title), summary=VALUES(summary), body=VALUES(body), category=VALUES(category), image=VALUES(image), photos=VALUES(photos), external=VALUES(external), featured=VALUES(featured), official=VALUES(official), status=VALUES(status), published_at=VALUES(published_at);
UPDATE noticias SET featured=0 WHERE id='official-1415894';
